Nb_experiment &lt;- 12

df_data_obs &lt;- df_data_fit |&gt; 
  mutate(
    Weight_obs = Weight,
    Reproduction_obs = Reproduction
    ) |&gt; 
  dplyr::select(-c(Weight, Reproduction))


Times_obs &lt;- seq(0,400, 14)

####### A

df_pred_A_FLYw &lt;- df_pred_full_A_FLYw |&gt; 
  filter(Time %in% Times_obs)

df_pred_Weight_A_FLYw &lt;- subset(df_pred_A_FLYw, Endpt == "Weight" & Time !=0)
df_pred_Reproduction_A_FLYw &lt;- subset(df_pred_A_FLYw, Endpt == "Reproduction" & Time !=0)

df_predobs_Reproduction_A_FLYw &lt;- df_data_obs |&gt; 
  filter(Time !=0 & Reproduction_obs != 0) |&gt;
  left_join(df_pred_Reproduction_A_FLYw, suffix = c("_obs", "_pred")) |&gt; 
  mutate(across(everything(), ~replace(.x, .x == -1, NA))) |&gt; 
  drop_na()


