6.8.1 Folds


Code
No_round &lt;- 1

f_count_fold &lt;- function(df_predobs_Weight, df_predobs_Reproduction, No_round) {

  df_predobs_Weight &lt;- df_predobs_Weight  |&gt;
  mutate(
    Ratio_predobs = predict.endpoint / Weight_obs,
    Residuals = predict.endpoint - Weight_obs
  )
  df_predobs_Reproduction &lt;- df_predobs_Reproduction  |&gt;
  mutate(
    Ratio_predobs = predict.endpoint / Reproduction_obs,
    Residuals = predict.endpoint - Reproduction_obs
  )

  Weight_count_fold2 &lt;- round(length(subset(df_predobs_Weight, Ratio_predobs &gt;= 0.5 & Ratio_predobs &lt;= 2)$Weight_obs) / length(df_predobs_Weight$Weight_obs) * 100, No_round)

  Weight_count_fold5 &lt;- round(length(subset(df_predobs_Weight, Ratio_predobs &gt;= 0.2 & Ratio_predobs &lt;= 5)$Weight_obs) / length(df_predobs_Weight$Weight_obs) * 100, No_round)

  Repro_count_fold2 &lt;- round(length(subset(df_predobs_Reproduction, Ratio_predobs &gt;= 0.5 & Ratio_predobs &lt;= 2)$Reproduction_obs) / length(df_predobs_Reproduction$Reproduction_obs) * 100, No_round)

  Repro_count_fold5 &lt;- round(length(subset(df_predobs_Reproduction, Ratio_predobs &gt;= 0.2 & Ratio_predobs &lt;= 5)$Reproduction_obs) / length(df_predobs_Reproduction$Reproduction_obs) * 100, No_round)

  df_predobs_Reproduction_0 &lt;- df_predobs_Reproduction |&gt;
    filter(Reproduction_obs &gt; 0) 

  Repro0_count_fold2 &lt;- round(length(subset(df_predobs_Reproduction_0, Ratio_predobs &gt;= 0.5 & Ratio_predobs &lt;= 2)$Reproduction_obs) / length(df_predobs_Reproduction_0$Reproduction_obs) * 100, No_round)

  Repro0_count_fold5 &lt;- round(length(subset(df_predobs_Reproduction_0, Ratio_predobs &gt;= 0.2 & Ratio_predobs &lt;= 5)$Reproduction_obs) / length(df_predobs_Reproduction_0$Reproduction_obs) * 100, No_round)

  df_fold &lt;- data.frame(
    Endpoint = c("Weight", "Reproduction", "Observed reproduction above 0"),
    '% of predictions in fold 2' = c(Weight_count_fold2, Repro_count_fold2, Repro0_count_fold2),
    '% of predictions in fold 5' = c(Weight_count_fold5, Repro_count_fold5, Repro0_count_fold5),
  check.names = FALSE
  )

  return(df_fold)

}

