6.8.2 RMSE per experiment


Code
f_RMSE_experiment &lt;- function(df_predobs_Weight, df_predobs_Reproduction){

  df_rmse_W &lt;- df_predobs_Weight %&gt;%
    group_by(ID_experiment) %&gt;%
    summarise(
      RMSE_Weight = sqrt(mean((predict.endpoint - Weight_obs)^2, na.rm = TRUE))
    )

  df_rmse_R &lt;- df_predobs_Reproduction %&gt;%
    group_by(ID_experiment) %&gt;%
    summarise(
      RMSE_Reproduction = sqrt(mean((predict.endpoint - Reproduction_obs)^2, na.rm = TRUE))
    )

  df_rmse &lt;- left_join(df_rmse_W, df_rmse_R)

  return(df_rmse)
}


df_rmse &lt;- purrr::map2_dfr(
