  )

make_plot &lt;- function(data, ids, metric_name) {

  lims &lt;- ylim_metric |&gt;
    filter(Metric == metric_name)

  ggplot(
    subset(data, ID_experiment %in% ids & Metric == metric_name),
    aes(
      x = Model,
      y = RMSE,
      color = Model
    )
  ) +
    geom_point(size = 2) +
    facet_grid(
      . ~ ID_experiment
    ) +
    coord_cartesian(
      ylim = c(lims$ymin, lims$ymax)
    ) +
    scale_color_manual(
      name = "Models",
      values = c(Nord_aurora, Nord_frost)
    ) +
    theme_bw() +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 8),
      strip.text = element_text(size = 8)
    ) +
    labs(
      x = "Model",
      y = "RMSE"
    )
}

